const body = $json.body || $json || {};
const headers = $json.headers || {};
const clean = (v) => String(v ?? '').trim();
const isUuid = (v) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(clean(v));

const authorization = clean(headers.authorization || headers.Authorization);
if (!authorization.startsWith('Bearer ') || authorization.length <= 7) {
  throw new Error('Worker RC1 requiere Authorization Bearer.');
}

const request_id = clean(body.request_id);
const usuario_id = clean(body.usuario_id);
const conversacion_id = clean(body.conversacion_id);
if (!isUuid(request_id) || !isUuid(usuario_id) || !isUuid(conversacion_id)) {
  throw new Error('Worker RC1 recibió identidad inválida.');
}

const accionObj = body.accion && typeof body.accion === 'object' && !Array.isArray(body.accion)
  ? body.accion
  : {};
const accion = clean(accionObj.tipo).toUpperCase();
const allowed = new Set([
  'CREAR_TAREA',
  'CREAR_OBJETIVO',
  'GUARDAR_MEMORIA',

  /*
    Las tres del negocio. Estaban listas en todos lados menos acá.

    El modelo las sabia pedir, el prompt se las ensenaba, el gateway tenia su
    ruta, la tabla de riesgo del gate les daba tier 3, los constraints de la
    base las admitian desde la v83 y el ejecutor existia desde la v84. Pero
    esta lista no las incluia, asi que el worker las rechazaba antes de
    llegar a pedir autorizacion.

    Efecto visible: el chat mostraba 'Operacion lista para registrar' y la
    pantalla de aprobaciones quedaba vacia. Una clienta lo reporto el 31 de
    agosto de 2026; el gate no habia visto un REGISTRAR_VENTA en su vida.
  */
  'REGISTRAR_VENTA',
  'AJUSTAR_STOCK',
  'CREAR_CONTACTO'
]);
if (!allowed.has(accion)) {
  throw new Error(`Acción no permitida en este endpoint: ${accion || 'vacía'}`);
}

const datos = accionObj.datos && typeof accionObj.datos === 'object' && !Array.isArray(accionObj.datos)
  ? accionObj.datos
  : {};

const payload = {
  mensaje: clean(body.mensaje),
  datos,
  metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata)
    ? body.metadata
    : {}
};

const authorize_body = {
  usuario_id,
  request_id,
  accion,
  payload,
  conversacion_id,
  origen: 'n8n-worker-gated-rc1'
};

return [{
  json: {
    request_id,
    usuario_id,
    conversacion_id,
    nombre: clean(body.nombre || 'Usuario'),
    mensaje: clean(body.mensaje),
    respuesta_gateway: clean(body.respuesta_gateway),
    accion,
    accion_datos: datos,
    plan: clean(body.plan || 'free'),
    origen: clean(body.origen || 'eos-web'),
    metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata) ? body.metadata : {},
    authorization,
    authorize_body,
    received_at: clean(body.received_at || new Date().toISOString())
  }
}];

const src = $('01 INT Preparar').first().json || {};
const auth = $input.first().json || {};
const isUuid = (v) => /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v || ''));

const execute = auth.ok === true && auth.execute === true && isUuid(auth.command_id);
const base = $env.EOS_APP_BASE_URL.replace(/\/$/, '');

return [{
  json: {
    ...src,
    auth,
    execute,
    command_id: isUuid(auth.command_id) ? auth.command_id : null,
    target_url: execute
      ? `${base}/api/internal/action-effects/v1`
      : `${base}/api/internal/worker-authorize/v1`,
    target_body: execute
      ? { command_id: auth.command_id }
      : src.authorize_body
  }
}];

const prep = $('03 INT Preparar Efecto').first().json || {};
const result = $input.first().json || {};
const auth = prep.auth || {};

const doneText = {
  CREAR_TAREA: 'La tarea quedó registrada.',
  CREAR_OBJETIVO: 'El objetivo quedó creado.',
  GUARDAR_MEMORIA: 'Guardé esa información en la memoria empresarial.',

  /*
    Las tres del negocio. Sin estas entradas caian en el texto generico
    'La accion quedo completada.', que despues de cargar una venta no le
    dice a nadie que la venta esta.
  */
  REGISTRAR_VENTA: 'La venta quedo registrada. La ves en Negocio > Ventas.',
  AJUSTAR_STOCK: 'Ajuste el stock. Lo ves en Negocio > Productos.',
  CREAR_CONTACTO: 'El contacto quedo guardado. Lo ves en Negocio > Contactos.'
};

if (!prep.execute) {
  const completed = auth.decision === 'completed';
  let respuesta = '';
  if (completed) respuesta = 'Esta acción ya había sido completada y no se repitió.';
  else if (auth.decision === 'approval' || auth.decision === 'approval_ready') respuesta = 'Esta acción requiere aprobación antes de ejecutarse.';
  else if (auth.decision === 'prepare' || auth.decision === 'recommend') respuesta = 'La acción quedó sin ejecución automática por la configuración de autonomía actual.';
  else respuesta = auth.reason || auth.error || 'La acción fue bloqueada por seguridad.';

  return [{
    json: {
      ok: auth.ok !== false,
      executed: false,
      idempotent: completed || auth.command_idempotent === true,
      decision: auth.decision || 'block',
      reason: auth.reason || auth.error || '',
      respuesta,
      request_id: prep.request_id,
      command_id: auth.command_id || null,
      accion: prep.accion,
      estado: completed ? 'completada' : null,
      resultado: auth.resultado || {}
    }
  }];
}

const success = result.ok === true && result.command_id;
return [{
  json: {
    ok: Boolean(success),
    executed: Boolean(success),
    idempotent: result.idempotent === true,
    request_id: prep.request_id,
    command_id: result.command_id || prep.command_id,
    accion: prep.accion,
    estado: result.estado || (success ? 'completada' : 'error'),
    effect_type: result.effect_type || '',
    effect_id: result.effect_id || null,
    resultado: result.resultado || {},
    respuesta: success
      ? (doneText[prep.accion] || 'La acción quedó completada.')
      : (result.error || 'No fue posible completar la acción interna.')
  }
}];

