      ? `${base}/api/internal/action-claims/v1`
      : `${base}/api/internal/worker-authorize/v1`,
    target_body: execute
      ? { operation: 'claim', command_id: auth.command_id, lease_seconds: 300 }
      : src.authorize_body
  }
}];

const prep = $('03 FILE Preparar Claim').first().json || {};
const claim = $input.first().json || {};
const auth = prep.auth || {};
const datos = prep.accion_datos || {};
const base = $env.EOS_APP_BASE_URL.replace(/\/$/, '');


/* =========================================================
   HELPERS
========================================================= */

const isUuid = (v) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
    String(v || '')
  );


const normalizar = (texto) =>
  String(texto || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');


/*
  n8n Code sandbox no expone URLSearchParams
  en esta versión.

  Construimos el query string manualmente
  usando encodeURIComponent.
*/
const construirQuery = (params) => {
  return Object.entries(params)
    .map(([key, value]) => {
      const k = encodeURIComponent(
        String(key ?? '')
      );

      const v = encodeURIComponent(
        String(value ?? '')
      );

      return `${k}=${v}`;
    })
    .join('&');
};


/* =========================================================
   VALIDAR CLAIM
========================================================= */

const claimed =
  prep.execute === true &&
  claim.ok === true &&
  claim.claimed === true &&
  isUuid(claim.command_id) &&
  isUuid(claim.lease_token) &&
  Number.isInteger(
    Number(claim.attempt_count)
  ) &&
  Number(claim.attempt_count) > 0;


/* =========================================================
   VALORES TERMINALES POR DEFECTO
========================================================= */

let archivo_url = '';
let archivo_tipo = '';
let archivo_nombre = '';

let estado = 'no_disponible';

let resultado = {};

let error_code = null;
let error_message = null;


/* =========================================================
   GENERAR_EXCEL
========================================================= */

if (
  claimed &&
  prep.accion === 'GENERAR_EXCEL'
) {

  const textoCompleto = [
    prep.mensaje,
    datos.tema,
    datos.tipo,
    datos.rubro,
    datos.negocio,
    datos.descripcion
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();


  /* -------------------------------------------------------
     ELEGIR PLANTILLA
  ------------------------------------------------------- */

  let plantilla = 'business';

  let rubro =
    datos.rubro ||
    'negocio_general';


  if (
    /finanzas personales|deuda|deudas|ahorro|presupuesto personal|salir de deudas/.test(
      textoCompleto
    )
  ) {
    plantilla = 'personal';
    rubro = 'persona_fisica';

  } else if (
    /restaurante|gastronomia|comida|hamburg|pizza|cafeteria|bar/.test(
      textoCompleto
    )
  ) {
    rubro = 'gastronomia';
  }


  /* -------------------------------------------------------
     NOMBRE DEL ARCHIVO
  ------------------------------------------------------- */

  const nombreBase =
    datos.negocio ||
    datos.nombre ||
    prep.nombre ||
    'usuario';


  archivo_nombre =
    plantilla === 'personal'
      ? `plan_financiero_eos_${normalizar(nombreBase)}.xlsx`
      : `control_negocio_eos_${normalizar(nombreBase)}.xlsx`;


  /* -------------------------------------------------------
     QUERY STRING

     IMPORTANTE:
     Ya NO usamos URLSearchParams.
  ------------------------------------------------------- */

  const query = construirQuery({
    tipo: 'excel',

    plantilla,

    nombre:
      archivo_nombre.replace(
        /\.xlsx$/i,
        ''
      ),

    rubro:
      String(rubro),

    negocio:
      String(nombreBase),

    tema:
      String(
        datos.tema ||
        prep.mensaje ||
        'control general'
      ),

    command_id:
      String(claim.command_id)
  });


  /* -------------------------------------------------------
     URL GOBERNADA
  ------------------------------------------------------- */

  archivo_url =
    `${base}/descargar?${query}`;


  archivo_tipo = 'excel';

  estado = 'completada';


  /* -------------------------------------------------------
     RESULTADO DURABLE
  ------------------------------------------------------- */

  resultado = {
    archivo_url,
    archivo_tipo,
    archivo_nombre,

    artifact_key:
      `${claim.command_id}.xlsx`,

    command_id:
      claim.command_id
  };
}


/* =========================================================
   PDF / WORD

   Todavía no conectados.
========================================================= */

else if (claimed) {

  archivo_tipo =
    prep.accion === 'GENERAR_PDF'
      ? 'pdf'
      : 'word';


  estado =
    'no_disponible';


  error_code =
    prep.accion === 'GENERAR_PDF'
      ? 'PDF_GENERATOR_NOT_CONNECTED'
      : 'WORD_GENERATOR_NOT_CONNECTED';


  error_message =
    prep.accion === 'GENERAR_PDF'
      ? 'El generador PDF todavía no está conectado al Worker Gate RC1.'
      : 'El generador Word todavía no está conectado al Worker Gate RC1.';


  resultado = {
    archivo_tipo,

    disponible: false,

    command_id:
      claim.command_id
  };
}


/* =========================================================
   TARGET FINAL
========================================================= */

const target_url =
  claimed
    ? `${base}/api/internal/action-results/v1`
    : `${base}/api/internal/worker-authorize/v1`;


const target_body =
  claimed
    ? {
        command_id:
          claim.command_id,

        lease_token:
          claim.lease_token,

        attempt_count:
          Number(
            claim.attempt_count
          ),

        estado,

        resultado,

        error_code,

        error_message
      }
    : prep.authorize_body;


/* =========================================================
   SALIDA
========================================================= */

return [
  {
    json: {
      ...prep,

      claim,

      claimed,

      archivo_url,

      archivo_tipo,

      archivo_nombre,

      terminal_estado:
        estado,

      terminal_resultado:
        resultado,

      target_url,

      target_body
    }
  }
];

const prep = $('05 FILE Preparar Resultado').first().json || {};
const final = $input.first().json || {};
const auth = prep.auth || {};
const claim = prep.claim || {};

if (!prep.execute) {
  const r = auth.resultado || {};
  const completed = auth.decision === 'completed';
  let respuesta = '';
  if (completed && r.archivo_url) respuesta = `El archivo ya estaba listo.\n\nDescargar archivo: ${r.archivo_url}`;
  else if (completed) respuesta = 'Esta generación ya había terminado y no se repitió.';
  else if (auth.decision === 'approval' || auth.decision === 'approval_ready') respuesta = 'La generación requiere aprobación antes de ejecutarse.';
  else if (auth.decision === 'prepare' || auth.decision === 'recommend') respuesta = 'La generación no se ejecutó automáticamente por la configuración de autonomía actual.';
  else respuesta = auth.reason || auth.error || 'La generación fue bloqueada por seguridad.';

  return [{
    json: {
      ok: auth.ok !== false,
      executed: false,
      idempotent: completed || auth.command_idempotent === true,
      decision: auth.decision || 'block',
      reason: auth.reason || auth.error || '',
      respuesta,
      request_id: prep.request_id,
      command_id: auth.command_id || null,
      accion: prep.accion,
      estado: completed ? 'completada' : null,
      archivo_url: r.archivo_url || '',
      archivo_tipo: r.archivo_tipo || '',
      archivo_nombre: r.archivo_nombre || '',
      resultado: r
    }
  }];
}

if (!prep.claimed) {
  const r = claim.resultado || {};
  const completed = claim.code === 'EOS_COMMAND_ALREADY_COMPLETED' || claim.estado === 'completada';
  return [{
    json: {
      ok: claim.ok !== false,
      executed: false,
      idempotent: claim.idempotent === true,
      decision: claim.code || 'not_claimed',
      reason: claim.error || claim.code || '',
      respuesta: completed && r.archivo_url
        ? `El archivo ya estaba listo.\n\nDescargar archivo: ${r.archivo_url}`
        : completed
          ? 'Esta generación ya estaba completada y no se repitió.'
          : 'La generación ya está siendo procesada por otro Worker; no se inició una segunda copia.',
      request_id: prep.request_id,
      command_id: claim.command_id || prep.command_id,
      accion: prep.accion,
      estado: claim.estado || null,
      archivo_url: r.archivo_url || '',
      archivo_tipo: r.archivo_tipo || '',
      archivo_nombre: r.archivo_nombre || '',
      resultado: r
    }
  }];
}

const finalized = final.ok === true;
const isExcel = prep.accion === 'GENERAR_EXCEL';
return [{
  json: {
    ok: finalized,
    executed: finalized && prep.terminal_estado === 'completada',
    idempotent: final.idempotent === true,
    request_id: prep.request_id,
    command_id: final.command_id || prep.command_id,
    accion: prep.accion,
    estado: final.estado || prep.terminal_estado,
    archivo_url: finalized && isExcel ? prep.archivo_url : '',
    archivo_tipo: prep.archivo_tipo,
    archivo_nombre: prep.archivo_nombre,
    resultado: final.resultado || prep.terminal_resultado || {},
    respuesta: finalized
      ? (isExcel
          ? `Tu Excel ya está listo.\n\nDescargar archivo: ${prep.archivo_url}`
          : 'Ese formato todavía no está disponible para generación gobernada en EOS.')
      : (final.error || 'No fue posible cerrar el resultado del archivo de forma segura.')
  }
}];

const body = $json.body || $json || {};
const headers = $json.headers || {};
const clean = (v) => String(v ?? '').trim();
const isUuid = (v) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(clean(v));

