    conversacion_id,
    nombre: clean(body.nombre || 'Usuario'),
    mensaje: clean(body.mensaje),
    respuesta_gateway: clean(body.respuesta_gateway),
    accion,
    accion_datos: datos,
    plan: clean(body.plan || 'free'),
    origen: clean(body.origen || 'eos-web'),
    metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata) ? body.metadata : {},
    authorization,
    authorize_body,
    received_at: clean(body.received_at || new Date().toISOString())
  }
