const ping = $input.first().json || {};
const authorized = ping.ok === true;
return [{json: {
  ...src,
  ping,
  authorized,
  effective_user_id: authorized ? src.usuario_id : '00000000-0000-0000-0000-000000000000'
}}];

const src = $('03 DASH Gate').first().json || {};
if (!src.authorized) {
  return [{json:{ok:false,executed:false,request_id:src.request_id,accion:src.accion,error:'Worker no autorizado.'}}];
}
const metricas = $input.all().map(i => i.json).filter(x => x && Object.keys(x).length);
let lineas = metricas.map(m => `- ${m.metric_label || m.metric_key || 'Métrica'}: ${m.metric_value || m.metric_number || 'sin valor'}`).join('\n');
if (!lineas) lineas = 'Todavía no hay métricas cargadas para este usuario.';
return [{json:{
  ok:true,executed:true,request_id:src.request_id,accion:src.accion,
  respuesta:`Dashboard EOS:\n${lineas}`,tipo:'texto'
}}];

